import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { z } from 'zod';
import { Agent } from '../src/agent';
import { ToolCallError } from '../src/errors';
import logger from '../src/logger';
import { mcpToFunctionTool, type MCPServer } from '../src/mcp';
import { Runner } from '../src/run';
import { RunContext } from '../src/runContext';
import { tool, type FunctionTool } from '../src/tool';
import { ScriptedModel, assistantMessage, functionCall } from '../src/testing';
import { setTraceProcessors, setTracingDisabled } from '../src/tracing';
import { defaultProcessor } from '../src/tracing/processor';
import type { Span } from '../src/tracing/spans';
import { TEST_TOOL } from './stubs';

const SECRET = 'synthetic-private-tool-failure';
const GENERIC_ERROR =
  'An error occurred while running the tool. Please try again.';
const REDACTED_ERROR = 'Tool execution failed. Error details are redacted.';
let spans: Span<any>[];

beforeEach(() => {
  spans = [];
  setTracingDisabled(false);
  setTraceProcessors([
    {
      async onTraceStart() {},
      async onTraceEnd() {},
      async onSpanStart() {},
      async onSpanEnd(span) {
        spans.push(span);
      },
      async shutdown() {},
      async forceFlush() {},
    },
  ]);
});

afterEach(() => {
  setTraceProcessors([defaultProcessor()]);
  setTracingDisabled(true);
  vi.restoreAllMocks();
});

async function runTool(
  failingTool: FunctionTool<any, any, any>,
  stream: boolean,
  traceIncludeSensitiveData: boolean,
  input = '{}',
  context: unknown = undefined,
) {
  const model = new ScriptedModel([
    [functionCall(failingTool.name, input, { callId: 'failure-call' })],
    [assistantMessage('recovered')],
  ]);
  const agent = new Agent({ name: 'Test', model, tools: [failingTool] });
  const runner = new Runner({ traceIncludeSensitiveData });
  const result = stream
    ? await runner.run(agent, 'start', { stream: true, context })
    : await runner.run(agent, 'start', { context });
  if ('completed' in result) {
    for await (const _event of result) {
      // Drain the stream to observe the final history and ended spans.
    }
    await result.completed;
  }
  expect(result.finalOutput).toBe('recovered');
  const nextInput = model.calls[1].request.input;
  expect(Array.isArray(nextInput)).toBe(true);
  const output = Array.isArray(nextInput)
    ? nextInput.find((item) => item.type === 'function_call_result')
    : undefined;
  expect(output).toBeDefined();
  return { result, nextInput, output };
}

describe('default function-tool failures', () => {
  it.each([
    { stream: false, sensitive: false, mcp: false },
    { stream: false, sensitive: true, mcp: false },
    { stream: true, sensitive: false, mcp: false },
    { stream: true, sensitive: true, mcp: false },
    { stream: false, sensitive: false, mcp: true },
    { stream: false, sensitive: true, mcp: true },
    { stream: true, sensitive: false, mcp: true },
    { stream: true, sensitive: true, mcp: true },
  ])(
    'redacts model history and spans: %j',
    async ({ stream, sensitive, mcp }) => {
      // Local diagnostic logging does not authorize model or trace disclosure.
      vi.spyOn(logger, 'dontLogToolData', 'get').mockReturnValue(false);
      const execute = async () => {
        throw Object.assign(new Error(SECRET), {
          cause: new Error(`cause-${SECRET}`),
        });
      };
      const server: MCPServer = {
        name: 'test-server',
        cacheToolsList: false,
        connect: async () => {},
        close: async () => {},
        listTools: async () => [],
        invalidateToolsCache: async () => {},
        callTool: execute,
      };
      const failingTool = mcp
        ? mcpToFunctionTool(
            {
              name: 'fail',
              inputSchema: {
                type: 'object',
                properties: {},
                required: [],
                additionalProperties: false,
              },
            },
            server,
            !stream,
          )
        : tool({
            name: 'fail',
            description: '',
            parameters: z.object({}),
            execute,
          });
      const { output, nextInput, result } = await runTool(
        failingTool,
        stream,
        sensitive,
      );
      expect(output).toMatchObject({
        output: { type: 'text', text: GENERIC_ERROR },
      });
      expect(JSON.stringify(nextInput)).not.toContain(SECRET);
      expect(JSON.stringify(result.history)).not.toContain(SECRET);
      expect(spans.some((span) => span.spanData.type === 'function')).toBe(
        true,
      );
      expect(JSON.stringify(spans.map((span) => span.toJSON()))).not.toContain(
        SECRET,
      );
      expect(
        spans.find((span) => span.spanData.type === 'function')?.error,
      ).toMatchObject({
        data: { error: REDACTED_ERROR },
      });
    },
  );

  it.each([false, true])(
    'does not inspect a thrown exception (stream=%s)',
    async (stream) => {
      const exception = new Proxy(
        {},
        {
          get() {
            throw new Error('Exception properties must not be read.');
          },
          getPrototypeOf() {
            throw new Error('Exception prototypes must not be read.');
          },
        },
      );
      const failingTool = tool({
        name: 'uninspectable',
        description: '',
        parameters: z.object({}),
        execute: () => {
          throw exception;
        },
      });
      const { output } = await runTool(failingTool, stream, true);
      expect(output).toMatchObject({
        output: { type: 'text', text: GENERIC_ERROR },
      });
    },
  );

  it.each([null, undefined, SECRET, 7])(
    'handles an arbitrary thrown value: %s',
    async (error) => {
      const failingTool = tool({
        name: 'primitive',
        description: '',
        parameters: z.object({}),
        execute: () => {
          throw error;
        },
      });
      expect(await failingTool.invoke(new RunContext(), '{}')).toBe(
        GENERIC_ERROR,
      );
    },
  );

  it.each([false, true])(
    'keeps custom feedback with sensitive tracing=%s',
    async (sensitive) => {
      const error = new Error(SECRET);
      const handler = vi.fn(() => 'Application-approved feedback');
      const failingTool = tool({
        name: 'custom',
        description: '',
        parameters: z.object({}),
        // Exercise the timeout wrapper's call-details cloning without timing out.
        timeoutMs: 10_000,
        execute: async () => {
          throw error;
        },
        errorFunction: handler,
      });
      const { output } = await runTool(failingTool, true, sensitive);
      expect(handler).toHaveBeenCalledWith(
        expect.any(RunContext),
        error,
        expect.any(Object),
      );
      expect(output).toMatchObject({
        output: { type: 'text', text: 'Application-approved feedback' },
      });
      const functionSpan = spans.find(
        (span) => span.spanData.type === 'function',
      );
      expect(functionSpan?.error).toMatchObject({
        data: { error: sensitive ? `Error: ${SECRET}` : REDACTED_ERROR },
      });
    },
  );

  it.each([false, true])(
    'redacts nested direct invocations without call details (stream=%s)',
    async (stream) => {
      const stringify = vi.fn(() => SECRET);
      const error = Object.assign(new Error(SECRET), { toString: stringify });
      const handler = vi.fn(() => 'Approved nested feedback');
      const inner = tool({
        name: 'inner',
        description: '',
        parameters: z.object({}),
        execute: () => {
          throw error;
        },
        errorFunction: handler,
      });
      const outer = tool({
        name: 'outer',
        description: '',
        parameters: z.object({}),
        execute: async (_input, context) => inner.invoke(context!, '{}'),
      });
      const { output } = await runTool(outer, stream, false);
      expect(output).toMatchObject({
        output: { type: 'text', text: 'Approved nested feedback' },
      });
      expect(handler).toHaveBeenCalledWith(
        expect.any(RunContext),
        error,
        undefined,
      );
      expect(stringify).not.toHaveBeenCalled();
      expect(JSON.stringify(spans.map((span) => span.toJSON()))).not.toContain(
        SECRET,
      );
      expect(
        spans.find((span) => span.spanData.type === 'function')?.error,
      ).toMatchObject({ data: { error: REDACTED_ERROR } });
    },
  );

  it.each(['custom', 'null'] as const)(
    'keeps runner malformed-JSON feedback outside the %s handler',
    async (mode) => {
      const handler = vi.fn(() => 'Approved parse feedback');
      const execute = vi.fn(() => 'unexpected');
      const failingTool = tool({
        name: 'parse_policy',
        description: '',
        parameters: z.object({}),
        execute,
        errorFunction: mode === 'custom' ? handler : null,
      });
      const { output } = await runTool(failingTool, false, false, SECRET);
      expect(output).toMatchObject({
        output: {
          type: 'text',
          text: 'An error occurred while parsing tool arguments. Please try again with valid JSON.',
        },
      });
      expect(handler).not.toHaveBeenCalled();
      expect(execute).not.toHaveBeenCalled();
      if (mode === 'custom') {
        await expect(
          failingTool.invoke(new RunContext(), SECRET),
        ).resolves.toBe('Approved parse feedback');
        expect(handler).toHaveBeenCalledOnce();
      } else {
        await expect(
          failingTool.invoke(new RunContext(), SECRET),
        ).rejects.toThrow();
      }
    },
  );

  it('does not inspect custom-handler exceptions for redacted tracing', async () => {
    const error = new Proxy(
      {},
      {
        get() {
          throw new Error('Must not inspect.');
        },
      },
    );
    const handler = vi.fn(
      (_context: RunContext, _error: unknown) => 'Approved feedback',
    );
    await runTool(
      tool({
        name: 'custom_redacted',
        description: '',
        parameters: z.object({}),
        execute: () => {
          throw error;
        },
        errorFunction: handler,
      }),
      false,
      false,
    );
    expect(handler.mock.calls[0]?.[1]).toBe(error);
  });

  it('preserves explicit null propagation and runner error identity', async () => {
    const error = new Error(SECRET);
    const failingTool = tool({
      name: 'propagate',
      description: '',
      parameters: z.object({}),
      execute: () => {
        throw error;
      },
      errorFunction: null,
    });
    await expect(failingTool.invoke(new RunContext(), '{}')).rejects.toBe(
      error,
    );
    await expect(runTool(failingTool, false, false)).rejects.toMatchObject({
      error,
      state: expect.anything(),
    });
    await expect(runTool(failingTool, true, false)).rejects.toBeInstanceOf(
      ToolCallError,
    );
  });

  it.each([
    { mode: 'legacy JSON', legacy: true, input: SECRET },
    { mode: 'factory JSON', legacy: false, input: SECRET },
    {
      mode: 'factory schema',
      legacy: false,
      input: JSON.stringify({ amount: SECRET }),
    },
  ])(
    'keeps invalid-input feedback fixed with logging enabled: $mode',
    async ({ mode, legacy, input }) => {
      vi.spyOn(logger, 'dontLogToolData', 'get').mockReturnValue(false);
      const execute = vi.fn(async () => 'unexpected');
      const failingTool = legacy
        ? { ...TEST_TOOL, invoke: execute }
        : tool({
            name: 'parse',
            description: '',
            parameters: z.object({ amount: z.number() }),
            execute,
          });
      const { output } = await runTool(failingTool, true, false, input);
      expect(execute).not.toHaveBeenCalled();
      expect(output).toMatchObject({
        output: {
          type: 'text',
          text:
            mode === 'factory schema'
              ? GENERIC_ERROR
              : 'An error occurred while parsing tool arguments. Please try again with valid JSON.',
        },
      });
      expect(JSON.stringify(spans.map((span) => span.toJSON()))).not.toContain(
        SECRET,
      );
    },
  );

  it('keeps opposite trace policies isolated across overlapping invocations', async () => {
    let release!: () => void;
    let markStarted!: () => void;
    const held = new Promise<void>((resolve) => {
      release = resolve;
    });
    const started = new Promise<void>((resolve) => {
      markStarted = resolve;
    });
    const failingTool = tool({
      name: 'overlap',
      description: '',
      parameters: z.object({}),
      execute: async (_input, context) => {
        if (context?.context === 'held') {
          markStarted();
          await held;
        }
        throw new Error(SECRET);
      },
      errorFunction: () => 'Approved feedback',
    });
    const redactedRun = runTool(failingTool, false, false, '{}', 'held');
    await started;
    try {
      await runTool(failingTool, false, true);
    } finally {
      release();
    }
    await redactedRun;
    const errors = spans
      .filter((span) => span.spanData.type === 'function')
      .map((span) => span.error?.data?.error);
    expect(errors).toEqual([`Error: ${SECRET}`, REDACTED_ERROR]);
  });
});

import { afterEach, beforeAll, describe, expect, it, vi } from 'vitest';
import { z } from 'zod';

import {
  Agent,
  ModelBehaviorError,
  Runner,
  UserError,
  setDefaultModelProvider,
  setTracingDisabled,
  type AgentInputItem,
  type Model,
  type ModelResponse,
  type ReasoningItem,
  type Session,
  type StreamEvent,
} from '../src';
import { defineOutputGuardrail } from '../src/guardrail';
import logger from '../src/logger';
import { RunResult } from '../src/result';
import { RunContext } from '../src/runContext';
import { runOutputGuardrails } from '../src/runner/guardrails';
import { RunState } from '../src/runState';
import { Usage } from '../src/usage';
import {
  ScriptedModelProvider,
  fakeModelMessage,
  fakeModelRefusal,
} from './stubs';
import { ScriptedModel, modelResponse, modelStream } from '../src/testing';

const MODEL_OUTPUT_SECRET = 'SECRET_STRUCTURED_FINAL_OUTPUT_4207';
const MISSING_OUTPUT_SECRET = 'SECRET_MISSING_STRUCTURED_OUTPUT_4208';
const OVERRIDDEN_PARSER_SECRET = 'SECRET_OVERRIDDEN_FINAL_OUTPUT_4209';
const PERSISTENCE_SECRET = 'SECRET_FINAL_OUTPUT_PERSISTENCE_4210';
const TEXT_OVERRIDE_SECRET = 'SECRET_TEXT_OVERRIDE_4211';
const INVALID_OUTPUT = JSON.stringify({ value: MODEL_OUTPUT_SECRET });
const OVERRIDDEN_PARSER_OUTPUT = JSON.stringify({
  value: OVERRIDDEN_PARSER_SECRET,
});
const REDACTED_OUTPUT_ERROR =
  'Invalid output type: final assistant output did not match the expected schema.';

const outputType = z.object({
  value: z.string().refine((value) => value !== MODEL_OUTPUT_SECRET, {
    message: `Rejected model output ${MODEL_OUTPUT_SECRET}`,
  }),
});

function responseWithInvalidOutput(): ModelResponse {
  return {
    output: [fakeModelMessage(INVALID_OUTPUT)],
    usage: new Usage(),
  };
}

function responseWithMissingOutput(): ModelResponse {
  return {
    output: [
      {
        type: 'reasoning',
        id: 'missing-output-reasoning',
        content: [{ type: 'input_text', text: MISSING_OUTPUT_SECRET }],
      } satisfies ReasoningItem,
    ],
    usage: new Usage(),
  };
}

class StreamingModel extends ScriptedModel {
  constructor(response: ModelResponse) {
    super([
      modelStream([
        {
          type: 'response_done',
          response: {
            id: 'redacted-final-output-response',
            output: response.output,
            usage: response.usage,
          },
        } as StreamEvent,
      ]),
    ]);
  }
}

function createAgent(model?: Model): Agent<unknown, any> {
  return new Agent({
    name: 'Structured output redaction agent',
    outputType,
    ...(model ? { model } : {}),
  }) as Agent<unknown, any>;
}

function expectRedactedError(
  error: unknown,
  secret = MODEL_OUTPUT_SECRET,
): void {
  expect(error).toBeInstanceOf(ModelBehaviorError);
  expect(error).toMatchObject({ message: REDACTED_OUTPUT_ERROR });
  expect(String(error)).not.toContain(secret);
  expect((error as Error & { cause?: unknown }).cause).toBeUndefined();
}

function overrideFinalOutputParser<TAgent extends Agent<unknown, any>>(
  agent: TAgent,
): TAgent {
  agent.processFinalOutput = (output: string): never => {
    throw new Error(`Overridden parser rejected ${output}`);
  };
  return agent;
}

function renderLoggerCalls(calls: unknown[][]): string {
  return calls.flat().map(String).join('\n');
}

function createRejectingSession(secret: string): Session {
  return {
    async getSessionId() {
      return 'rejecting-final-output-session';
    },
    async getItems() {
      return [];
    },
    async addItems(_items: AgentInputItem[]) {
      throw new Error(`Persistence rejected ${secret}`);
    },
    async popItem() {
      return undefined;
    },
    async clearSession() {},
  };
}

async function captureRunError(stream: boolean): Promise<unknown> {
  const response = responseWithInvalidOutput();
  const agent = createAgent(
    stream
      ? new StreamingModel(response)
      : new ScriptedModel([modelResponse(response)]),
  );

  try {
    if (stream) {
      const result = await new Runner().run(agent, 'go', {
        stream: true,
      });
      await result.completed;
    } else {
      await new Runner().run(agent, 'go');
    }
  } catch (error) {
    return error;
  }
  throw new Error('Expected the run to fail.');
}

async function captureOverriddenParserRunError(
  stream: boolean,
): Promise<unknown> {
  const response: ModelResponse = {
    output: [fakeModelMessage(OVERRIDDEN_PARSER_OUTPUT)],
    usage: new Usage(),
  };
  const agent = overrideFinalOutputParser(
    createAgent(
      stream
        ? new StreamingModel(response)
        : new ScriptedModel([modelResponse(response)]),
    ),
  );

  return captureOverriddenParserRunErrorWithAgent(agent, stream);
}

async function captureOverriddenParserRunErrorWithAgent(
  agent: Agent<unknown, any>,
  stream: boolean,
): Promise<unknown> {
  try {
    if (stream) {
      const result = await new Runner().run(agent, 'go', { stream: true });
      await result.completed;
    } else {
      await new Runner().run(agent, 'go');
    }
  } catch (error) {
    return error;
  }
  throw new Error('Expected the overridden parser to fail.');
}

