      new MemorySession({ initialItems: [hidden] }),
    );
    const model = new ScriptedModel([
      {
        type: 'stream',
        events: (async function* () {
          yield {
            type: 'response_done' as const,
            response: {
              id: 'failed-stream',
              output: [assistantMessage('partial')],
              usage: { inputTokens: 0, outputTokens: 0, totalTokens: 0 },
