function credentialedS3Manifest(
  strategy: MountStrategy,
  options: { mountPath?: string } = {},
): Manifest {
  return new Manifest({
    entries: {
      remote: s3Mount({
        bucket: 'example',
        accessKeyId: 'ACCESS_KEY_SENTINEL',
        secretAccessKey: 'SECRET_KEY_SENTINEL',
        mountStrategy: strategy,
        ...options,
      }),
